namespace sv_f6542055aae24f349d0a975f59cd8163;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

.catalog-container {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
}

.catalog-sidebar {
    width: 25%;
    min-width: 220px;
    border-right: 1px solid #ddd;
    padding-right: 1.5rem;
}

.catalog-sidebar h3 {
    margin-top: 0;
}

.catalog-main {
    width: 75%;
    flex: 1;
}

.filter-section {
    margin-bottom: 1.25rem;
}

.filter-section h4 {
    margin-bottom: 0.5rem;
}

.filter-section label {
    display: block;
    margin-bottom: 0.35rem;
}

.filter-section input[type="number"] {
    width: 100%;
    padding: 0.3rem 0.5rem;
    margin-top: 0.25rem;
    box-sizing: border-box;
}

.checkbox-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-top: 1rem;
}

.toolbar {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.toolbar select {
    padding: 0.4rem 0.6rem;
}

.results-summary {
    color: #555;
    font-size: 0.9rem;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.25rem;
}

.product-card {
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 1rem;
    cursor: pointer;
    transition: box-shadow 0.2s;
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.12);
}

.product-image {
    background: #f0f0f0;
    height: 150px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 4px;
    margin-bottom: 0.75rem;
    color: #888;
    font-size: 0.85rem;
    text-align: center;
    padding: 0.5rem;
}

.product-info {
    flex: 1;
    display: flex;
    flex-direction: column;
}

.product-name {
    margin: 0 0 0.4rem;
    font-size: 1rem;
}

.product-price {
    font-weight: bold;
    color: #2a7d2a;
    margin: 0 0 0.4rem;
}

.product-rating {
    color: #f5a623;
    margin-bottom: 0.4rem;
}

.badge-out-of-stock {
    display: inline-block;
    background: #dc3545;
    color: #fff;
    font-size: 0.75rem;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    margin-bottom: 0.5rem;
    width: fit-content;
}

.btn-add-to-cart {
    margin-top: auto;
    padding: 0.5rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-add-to-cart:disabled {
    background: #aaa;
    cursor: not-allowed;
}

.pagination {
    display: flex;
    gap: 0.4rem;
    margin-top: 1.5rem;
    justify-content: center;
    flex-wrap: wrap;
}

.pagination .btn {
    padding: 0.4rem 0.75rem;
    border: 1px solid #ddd;
    background: #fff;
    border-radius: 4px;
    cursor: pointer;
}

.pagination .btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.pagination .btn-active {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

.btn-primary {
    background: #0d6efd;
    color: #fff;
    border: none;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    cursor: pointer;
}

.btn-secondary {
    background: #6c757d;
    color: #fff;
    border: none;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    cursor: pointer;
}

.loading, .empty-results {
    text-align: center;
    padding: 3rem 1rem;
    color: #666;
    font-size: 1.1rem;
}

.alert-danger {
    background: #f8d7da;
    color: #842029;
    padding: 1rem;
    border-radius: 4px;
    border: 1px solid #f5c2c7;
}

