+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.loading, .empty-results {
+    text-align: center;
+    padding: 3rem 1rem;
+    color: #666;
+    font-size: 1.1rem;
+}
+
+.alert-danger {
+    background: #f8d7da;
+    color: #842029;
+    padding: 1rem;
+    border-radius: 4px;
+    border: 1px solid #f5c2c7;
+}
+

